// SigTrace-Alloc - leak detection demo
var seen = {};
function alloc(id, bytes) { seen[id] = (seen[id] || 0) + bytes; }
function free(id) { delete seen[id]; }
alloc("buf-a", 1024); alloc("buf-b", 2048); alloc("buf-c", 512);
free("buf-b");
var leaked = Object.keys(seen);
console.log("Tool model: sigtrace");
console.log("Live allocations: " + Object.keys(seen).length);
console.log(leaked.length ? "LEAK: " + leaked.join(", ") + " never freed" : "CLEAN: no leaks");

